import java.util.*;

class Solution {
  private int answer;

  public int countPairs(TreeNode root, int distance) {
    answer = 0;
    dfs(root, distance);
    return answer;
  }

  private int[] dfs(TreeNode node, int d) {
    int[] count = new int[d + 1];
    if (node == null) return count;
    if (node.left == null && node.right == null) {
      count[1] = 1;
      return count;
    }
    int[] a = dfs(node.left, d), b = dfs(node.right, d);
    for (int i = 1; i <= d; i++) for (int j = 1; j + i <= d; j++) answer += a[i] * b[j];
    for (int i = 2; i <= d; i++) count[i] = a[i - 1] + b[i - 1];
    return count;
  }
}
